(87, 'S and M Cleaning and Support Services', 'c-linkdanny@smcleaningsupport.co.uk', 'Unit 12b Evelyn Court, Grinstead Road, London, SE8 5AD', '02084 69400', '07539 931088', '7361786', 'specialist-logo.png', 'A Professional Family Run Company', 'www.smcleaningsupport.co.uk', '<h3>S and&nbsp;M Cleaning and Support Services is a professional family run office cleaning and support services company with a comprehensive range of solutions available for your project.</h3>\r\n<p>S and&nbsp;M Cleaning provide services including ,&nbsp;<strong>BMU Cleaning, Reach &amp; wash window cleaning, MEWP Work,</strong>&nbsp;<strong>Rope Access</strong>,&nbsp;<strong>Building Repairs</strong>,&nbsp;<strong>Painting</strong>,&nbsp;<strong>Re-</strong>p<strong>ointing</strong>&nbsp;and&nbsp;<strong>mastic&nbsp;</strong>to a variety of commercial clients and have a wealth of experience delivering an excellent service; our teams are trained and are fully capable of providing an optimum service for your requirements.</p>\r\n<p>The key to our success is a committed and dedicated team of cleaning professionals and experts. We ensure that all team management are focused on the same goal&nbsp;and business objectives &ndash; to exceed our clients expectations. Our growing portfolio and client base is evidence of our growing reputation.</p>\r\n<p>We are available to provide a free quotation using the contact details included here.</p>', 1, 3, '2018-01-23 12:02:22', NULL, NULL, 5),
(102, 'T and T Group', 'c-linkjohn@tandtgroup.co.uk', 'WD6 2FR', '02079 936222', '07463 798914', '09275992', 'TT-GROUP-Logo-Updation-1-RR.jpg', 'Construction Specialists in strip–out, demolition, ground and frame works', 'www.tandtgroup.co.uk', '<p><span style=\"font-size: 11pt;\">T&amp;T Group are the leading Construction Specialists in <strong>strip</strong>&ndash;<strong>out</strong>, <strong>demolition, ground and frame works</strong>.&nbsp;We work in both the Commercial and Residential sectors and mainly cover London and the surrounding counties.</span></p>\r\n<p><span style=\"font-size: 11pt;\">We are able to undertake projects on both a Principal Contractor and Sub-Contractor basis and are fully insured, registered waste carriers (both standard and hazardous).</span></p>', 1, 3, '2016-10-09 15:51:55', NULL, NULL, 5),
