(1158, 'JFE Attridge Scaffolding Services Co. Ltd.', 'c-linkinfo@attridge-scaffolding.co.uk', 'The Levels Ind. Est., Rugeley, Staffs. WS15 1RD', '', '0', '1066986', 'specialist-logo.png', '40 YEARS OF EXCELLENCE', 'www.attridge-scaffolding.co.uk', NULL, 1, 3, '2017-06-07 16:33:32', NULL, NULL, 5),
(1160, 'Ligneous Group Ltd', 'c-linkcolin@ligneousgroup.com', '121 New Zealand Avenue, Walton on Thames, Surrey KT12 1QD', '02081 917955', '07971 571040', '10630539', 'ligneouskitchens-BlueBlack.jpg', 'Beautiful German and Bespoke Kitchens', 'www.ligneouskitchens.com', '<p><span style=\"font-size: 11pt;\">Ligneous Kitchens</span></p>\r\n<p><span style=\"font-size: 11pt;\">Founded by cabinet makers and furniture designers, Ligneous Kitchens are committed to designing kitchens that inspire. We create beautiful led German and bespoke kitchens and furniture. Partnered with Eggersmann, KH System, Bax, Stormer and Brigitte, all German brands. The design ranges are equisite and manufactured to the very highest precision and quality and cover all price groups.</span></p>\r\n<p><span style=\"font-size: 11pt;\">Working hand in hand with our bespoke joinery arm Ligneous Designs, we have unrivaled abilty to offer branded kitchens togehter with a full bespoke joinery for any high end residential project.</span></p>\r\n<p><span style=\"font-size: 11pt;\">We have extensive experience working with architects, interior designers, building contractors and property developers. Our goal is to ensure that any project we undertake runs as smoothly as possible. Maintaining regular dialogue with all the professionals involved in a project is key to our success. We provide our clients with regular updates on how a project is progressing and endeavour to minimise the disruption whilst installation takes place. Ultimately, our greatest emphasis is on accommodating our client&rsquo;s needs and ensuring superior results.</span></p>\r\n<p><span style=\"font-size: 11pt;\">Ligneous Designs continue to gain work by recommendation through a strong reputation for client satisfaction.&nbsp; All our work is finished to the highest specification and we provide a full aftercare service.</span></p>', 1, 3, '2017-07-26 13:37:21', NULL, NULL, 5),
