(2145, 'T L Richards Limited', 'c-linkinfo@tlrweb.co.uk', 'First Floor Hill House, 23-25 Spur Road, Cosham, Portsmouth, PO6 3DY', '02392 593808', '07584 197628', '03959032', 'tlr-painter-decorator-logo.png', 'TLR Painting Contractors', 'www.tlrweb.co.uk', 'TLR Painter and Decorators are a family run company with over 40 years of experience in the painting, decorating and renovation trade. We have worked for a number of large companies including Vale Garden Houses, Edward Bulmer Paints and Homes & Gardens. Our work has also included small family homes, new builds and large renovation projects.', 1, 3, '2021-01-19 07:46:27', NULL, NULL, 5),
(2146, 'Dorplan Contracts Limited', 'c-linkenquiries@dorplan.co.uk', 'Karoo Close, Bexwell Business Park, Bexwwll, Norfolk. PE38 9GA', '01366 386800', '01366 386800', '1338059', 'DORPLAN LOGO.jpg', 'Certified Doorsets : Delivering Assurance', 'www.dorplan.co.uk', '<p class=\"myclass\" style=\"font-family: sofia_pro_softlight;\"><span style=\"font-size: 11pt;\">Certified Doorsets : Delivering Assurance</span></p>\r\n<p class=\"myclass\" style=\"font-family: sofia_pro_softlight;\"><span style=\"font-size: 11pt;\">We specialise in manufacturing pre-hung timber doorsets with both in-house and 3rd Party Certification and Test Evidence. We offer both Standard &amp; Bespoke Fire Doorsets, PAS24 Doorsets, Acoustic Doorsets up to 55dB and External Timber Doorsets. Along with this, we offer an extensive range of ironmongery tested with our doors to ensure compliance. We can match any specification of ironmongery, with various finishes, from our standard Satin Stainless Steel range, through to more bespoke finishes, such as Satin Brass, Matt Black and Matt Bronze.</span></p>\r\n<p class=\"myclass\" style=\"font-family: sofia_pro_softlight;\"><span style=\"font-size: 11pt;\">Each project will have an assigned contracts / projects manager which will be your single point of contact, through the manufacturing sign off, production, delivery and technical advice.</span></p>\r\n<p class=\"myclass\" style=\"font-family: sofia_pro_softlight;\"><span style=\"font-size: 11pt;\">Our capacity is around 600 doorsets per week. Our current lead time is around 8-10 weeks from confirmation of details.</span></p>', 1, 3, '2021-01-19 07:46:27', NULL, NULL, 5),
(2149, 'Sharper Screeding Services', 'c-linksharperscreedingservs@mail.com', '45 Navigators Way, Hedge End, Southampton, SO30 2GP', '07525 899938', '07525 899938', '11972690', 'sharper.jpg', 'Screeding Contractor in the South East', '', NULL, 1, 3, '2021-01-19 07:46:27', NULL, NULL, 5),
