(2352, 'Formal Property Construction Limited', 'c-linkenquiries@formalproperty.com', 'Fulham Park House, 1a Chesilton Road, London, SW6 5AA', '07855423999', '', '10712697', 'formal_logo-2.png', NULL, 'www.formalproperty.com', 'Formal Property Group is a London based property company focused primarily on residential property development within Greater London.\n\nThe company is led by functional and aesthetic design.  We work both independently and alongside investors to create ‘property with purpose’.  Each and every one of our property developments is designed to meet and exceed the expectations of the local market.  This helps us ensure that our homes will always find a buyer, no matter what the economic conditions.\n\nOver the years, we have built a network of agents and market knowledge that enables us to uncover value in what is an increasingly competitive sector.  The team of professionals with whom we work are able to facilitate quick assessments and streamline transactional processes to ensure that no opportunity is wasted.\n\nIn what is a challenging indsutry, our aim is to act with honesty and integrity in all that we do.', 0, 2, '2019-02-27 20:28:58', NULL, NULL, 5),
(2432, 'Albany Brent Group Ltd', 'c-linktenders@albany.group', 'Absolute House, Coptfold Hall Farm, Writtle Road, Ingatestone, CM4 0EL', '02084 984780', '02084 984780', '08575528', 'logoabgro.png', 'Specialist Roofing Contractors', 'www.albanybrent.co.uk', '<p class=\"myclass\" style=\"font-family: sofia_pro_softlight;\"><span style=\"font-size: 11pt;\">Albany Brent Group Limited are Specialist Roofing Contractors who have been established since 1992.</span></p>\r\n<p class=\"myclass\" style=\"font-family: sofia_pro_softlight;\"><span style=\"font-size: 11pt;\">During our years of service we&rsquo;ve gained a growing reputation for high quality works and carry employers liability insurance for &pound;10,000,000 and public/products insurance for &pound;10,000,000, we can also offer full insurance backed guarantees on all of our waterproofing packages Works are carried out by our in-house operatives and are not sub-contracted out. </span></p>\r\n<p class=\"myclass\" style=\"font-family: sofia_pro_softlight;\"><span style=\"font-size: 11pt;\">All Albany Brent Group Limited operatives are fully trained in various courses including Health and Safety and carry current CSCS cards.</span></p>', 1, 3, '2021-01-19 07:46:35', NULL, NULL, 5),
(2433, 'pr@lignumjoinery.com', 'c-linkpr@lignumjoinery.com', '', '', '0', '13139392', 'specialist-logo.png', '', '', NULL, 1, 3, '2020-08-19 11:28:47', NULL, NULL, 5),
(2445, 'B-Line Ltd', 'c-linkproperty@b-line.co', '5A Lombard Road | Wimbledon | London | SW19 3TZ', '02083 912701', '07484 211575', '09659501', 'unnamed.png', 'B-Line - B-Safe specialist contractors in concrete cutting, structural modification, demolition/deconstruction, groundworks, fire protection and training!', 'www.b-line.co', '<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">B-Line Ltd is a multifaceted engineering and construction contractor based in Wimbledon with specialisms in structural modification, civils, infrastructure, deconstruction, passive fire protection and a range of property services as well as being one of the UK&rsquo;s leading concrete cutting contractor.</p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">&nbsp;</p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">We have worked on many high-profile projects across London and the South East of England for some of the UK&rsquo;s most prominent contractors in numerous sectors. We cover the following fields of work:</p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">&nbsp;</p>\r\n<ul style=\"margin-left: .375in; direction: ltr; unicode-bidi: embed; margin-top: 0in; margin-bottom: 0in;\" type=\"disc\">\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">Concrete Cutting / Diamond Drilling </span></li>\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">Structural Modification / Cut &lsquo;n&rsquo; Carve</span></li>\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">Passive Fire Protection </span></li>\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">Civils and Infrastructure </span></li>\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">Robotic &lsquo;Brokk&rsquo; Demolition </span></li>\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">Demolition and Deconstruction </span></li>\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">Internal Strip Out </span></li>\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">Groundworks / Piling</span></li>\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">Concrete Works </span></li>\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">Facade Retention </span></li>\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">Temporary / Enabling Works</span></li>\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">Telecoms Infrastructure</span></li>\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">Modular Construction </span></li>\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">General Construction</span></li>\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">Cladding Installation</span></li>\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">Abrasive Blasting </span></li>\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">Pull/Load Testing </span></li>\r\n<li style=\"margin-top: 0; margin-bottom: 0; vertical-align: middle;\"><span style=\"font-family: \'Segoe UI\'; font-size: 11.0pt;\">Equipment and Plant Hire </span></li>\r\n</ul>\r\n<p style=\"margin: 0in; margin-left: .375in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">&nbsp;</p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\"><span style=\"font-weight: bold;\">Our Training Centre:</span></p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">B-Line Training Ltd is our in-house training centre which is CITB, NDTG, UKATA and the British Safety Council approved providing a range of industry accredited courses including CCDO, Asbestos Awareness, SSST S, SMSTS and more.</p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">&nbsp;</p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\"><span style=\"font-weight: bold;\">Our Recruitment Centre:</span></p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">We also supply site operatives ranging from labourers, CCDO demolition workers, supervisors, plant/machine drivers, traffic marshals, fire marshals, carpenters, bricklayers and others to main contractors across London and the South East.</p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">&nbsp;</p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\"><span style=\"font-weight: bold;\">Our Sectors:</span></p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">Commercial, Residential, Infrastructure, Rail, Industrial, Health, Education, Leisure, Telecoms and Nuclear.</p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">&nbsp;</p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\"><span style=\"font-weight: bold;\">Our Projects:</span></p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">Hinkley Point C, Wimbledon Lawn Tennis Club, St Bart&rsquo;s Hospital, Battersea Power Station, The Royal Opera House, The Royal College of Surgeons, Earls Court Exhibition Centre, BBC White City, Chelsea Barracks, Buckingham Gate, K1 Knightsbridge, Triton Square, The Stage Shoreditch, Southampton University, Willesden Junction Station Depot and many more.</p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">&nbsp;</p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\"><span style=\"font-weight: bold;\">Our Clients:</span></p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">KierBAM, Sir Robert McAlpine, Keltbray, Spencer Group, Collins Construction, Osborne, Paragon Interserve, Deconstruct, J.Reddington, Landmark, Bouygues, Paye Stone &amp; Restoration, Modus, General Demolition.</p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">&nbsp;</p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\"><span style=\"font-weight: bold;\">Our Accreditations: </span></p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">Constructionline Gold, ISO 9001, ISO 14001, ISO 45001, CHAS, Acclaim, FIRAS, Construction Fixings Association, Achilles RISQS, CITB, NDTG, UKATA, British Safety Council.</p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">&nbsp;</p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\"><span style=\"font-weight: bold;\">Our Equipment:</span></p>\r\n<p style=\"margin: 0in; font-family: \'Segoe UI\'; font-size: 11.0pt;\">B-Line own over &pound;1mil worth of cutting edge plant and equipment including Brokk Robots, concrete cutting equipment as well being the sole owners of the most powerful tracked wire saw in Europe used to remove the 1000 ton portal beams at Earls Court Exhibition Centre.</p>', 1, 3, '2021-01-19 07:46:35', NULL, NULL, 5),
