(2504, 'Gaia Climate Solutions Ltd.', 'c-linksteven@gaia.co.uk', 'Unit 4, Brickfields Business Park, Woolpit, Suffolk IP30 9QS', '01359 242400', '07957 594920', '2424430', 'gaia.png', 'We offer total underfloor heating solutions across the UK and Ireland, specialising in the design, supply and installation of both wet and electric underfloor heating systems as well as frost protection, ice and snow melting systems and controls.', 'www.gaia.co.uk', '<p><span style=\"font-family: sofia_pro_softlight;\">With over 30 years experience and our wealth of knowledge in the Underfloor Heating industry, we know how important it is to you that a we deliver a professional and seamless solution that&rsquo;s delivered on time and to budget. </span></p>\r\n<p><span style=\"font-family: sofia_pro_softlight;\">At Gaia we have a dedicated team of Account Managers providing you with a professional service from initial project specification through to project completion. Our wide range of underfloor solutions can be used for projects ranging from new build residential or commercial construction, office or residential renovations and self build projects.</span></p>\r\n<p><span style=\"font-family: sofia_pro_softlight;\">Our in-house team of CAD designers offer specialist solutions to meet the needs of your project. We use the latest in design technology and heat loss calculation software, giving you peace of mind that every system is backed with a full project specific CAD drawing, system schematics and technical support.</span></p>\r\n<p><span style=\"font-family: sofia_pro_softlight;\">Our product quality is complemented with market leading warranties, giving you a durable, long lasting system at a very competitive price.<br /></span></p>', 1, 3, '2021-01-19 07:46:36', NULL, NULL, 5),
(2514, 'T Vaughan Limited', 'c-linkradka@tvaughan.co.uk', 'Botany Way, Purfleet, United Kingdom, RM19 1SR', '01708 680421', '07944 438530', '7120692', 'T-Vaughan-Logo.png', 'RC Frame | Groundworks | Civil Engineering | Basements', 'http://www.tvaughan.co.uk', NULL, 1, 3, '2021-01-19 07:46:37', NULL, NULL, 5),
(2519, 'TGM Contractors Ltd', 'c-linkphilb@tgmcontractors.co.uk', 'Arch House, 2-4 High Street, Chalfont St Peter, Buckinghamshire, SL9 9QA', '01753 888031', '01753 888031', '07803770', 'TGM.png', '', 'http://www.tgmcontractors.co.uk', NULL, 1, 3, '2021-01-19 07:46:37', NULL, NULL, 5),
(2521, 'kevin@southernmasticroofing.co.uk', 'c-linkkevin@southernmasticroofing.co.uk', '', '', '0', '10009505', 'specialist-logo.png', '', '', NULL, 1, 3, '2020-08-19 11:28:47', NULL, NULL, 5),
(2522, 'Vivant Homes (Bath Road) Limited', 'c-linkinfo@vivanthomes.co.uk', 'The Courtyard, High Street, Ascot, England, SL5 7HP', '02038587879', '', '11711250', 'Vivant-Homes-Ltd-Property-Developments-London-Brand-Dark-Norm.png', NULL, 'www.vivanthomes.co.uk', 'Vivant have rapidly built a reputation for being innovative and more forward thinking.  This is from our experiences outside of the industry, as well as shared knowledge with third party partners and pioneering construction methodology.\nWe have an impressive portfolio of backgrounds within the leadership team, including a strong understanding of financial risks, collected from over two decades of international finance experience.  This adds a layer of risk analysis that sets us apart.\nWe use a quantitative approach to the whole development process. Through forensic analysis of the viability of locations with our model, Vivant can identify targeted developments that fit our investors’ risk reward profile.\nThis level of granularity and control is embedded at purchase through a joint venture with equity partners. It continues throughout, with process optimisation and rigorous cost control, to maximise profits for our investors.', 0, 2, '2021-01-19 07:46:37', NULL, NULL, 5),
(2546, 'tomcuffe@shieldenvironmental.co.uk', 'c-linktomcuffe@shieldenvironmental.co.uk', '', '', '0', '5938654', 'specialist-logo.png', '', '', NULL, 1, 3, '2020-08-19 11:28:47', NULL, NULL, 5);
