(3842, 'Levismar Formwork & Groundwork Ltd', 'c-linkmarius@levismar.co.uk', 'Mulben North Hill, Horndon-On-The-Hill, Stanford-Le-Hope, England, SS17 8QA', '02036 733078', '07576 245230', '08695525', 'Cline.png', 'Concrete Structures on time on budget with safety first.', 'www.levismar.co.uk', '<p class=\"myclass\" style=\"font-family: sofia_pro_softlight;\">Established in 2013 we are a young and aspiring Company specialising in Reinforced Concrete Structures, Groundworks and Civil Engineering. We are keen to continue steady growth and always seeking new clients and projects.&nbsp;</p>', 1, 3, '2021-01-19 07:47:30', NULL, NULL, 5),
(3846, 'Premier Contracting (Southern) Ltd', 'c-linkvicky@premiergrp.co.uk', '187 Lenthall Avenue, Grays, England, RM17 5AA', '08452 690009', '07540 051120', '08606193', 'Premier Contracting 1.png', 'No job is too big or small', 'www.premiergrp.co.uk', '<p class=\"myclass\" style=\"font-family: sofia_pro_softlight;\">We are specialist Contractors providing fit out &amp; building solutions to Hotels, Leisure Facilities &amp; Care Homes across the UK. We provide all aspects of the fitout and refurbishment programme from the conceptual design to full installation and fulfilment.</p>\r\n<ul>\r\n<li class=\"myclass\" style=\"font-family: sofia_pro_softlight;\">Project Management</li>\r\n<li class=\"myclass\" style=\"font-family: sofia_pro_softlight;\">Budget Control</li>\r\n<li class=\"myclass\" style=\"font-family: sofia_pro_softlight;\">Design Services</li>\r\n<li class=\"myclass\" style=\"font-family: sofia_pro_softlight;\">Procurement Services</li>\r\n<li class=\"myclass\" style=\"font-family: sofia_pro_softlight;\">Building Control Management</li>\r\n<li class=\"myclass\" style=\"font-family: sofia_pro_softlight;\">Working with clients to minimise disruption to the core business operationsduring works</li>\r\n<li class=\"myclass\" style=\"font-family: sofia_pro_softlight;\">Delivery of a full building &amp; fitout service to meet our customers expections</li>\r\n</ul>\r\n<p class=\"myclass\" style=\"font-family: sofia_pro_softlight;\">Clients and designers are always welcome to visit - we have an extensive library, where we are happy to discuss and assist with any future project</p>', 1, 3, '2021-01-19 07:47:31', NULL, NULL, 5),
