INSERT INTO `feedback` (`id`, `user_id`, `account_id`, `feedback_type`, `sentiment`, `created_at`) VALUES
(1, 16280, 1, 2, 'Make releases great again', '2023-03-02 08:19:55'),
(2, 16527, 1, 1, 'Awesome suggestion incoming, Keep calm until then!', '2023-03-02 08:20:22'),
(3, 21424, 2673, 2, 'Can a mechanism be added to allow sending out a single document to all subcontractors as an addendum rather that having to issue as an addendum to each package.', '2023-03-03 13:54:40'),
(4, 18068, 18305, 1, 'Geomapping caribbean islands. \n\n\nJamaica first. \n\nhttps://www.gov.uk/government/collections/cariforum-uk-economic-partnership-agreement\n\n', '2023-03-04 09:24:18'),
(5, 22802, 22462, 1, 'A bespoke consultants contract would be much better than adapting the purchase order contract', '2023-11-29 21:18:57'),
(6, 21506, 21312, 1, 'I want to be able to delete projects ', '2024-01-02 16:18:40');
